#ifndef UTIL_H
#define UTIL_H

#include <fmt/format.h>
#include <yaml-cpp/yaml.h>
#include <sys/stat.h>
#include <concepts>
#include <functional>
#include <initializer_list>
#include <memory>
#include <regex>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

namespace ws {

typedef int FileDescriptor;
constexpr FileDescriptor invalid_file_descriptor = -1;

std::string StringToLower(std::string str) noexcept;
std::string StringToUpper(std::string str) noexcept;
std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept;
std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) noexcept;
std::vector<std::string> SplitStringToLines(const std::string& str) noexcept;
YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields = {});
void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field);
constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept;
void SetFileDescriptorAsNonblocking(FileDescriptor fd);
[[noreturn]] void ThrowLastSystemError();
std::uint32_t CurrentThreadId() noexcept;
void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip = 0) noexcept;
std::string Backtrace(std::size_t size, std::size_t skip = 0, std::string_view prefix = "") noexcept;

template <typename T, typename... Args>
class Singleton {
public:
    static T& Instance(Args&&... args);
};

template <typename T, typename... Args>
class SingletonPtr {
public:
    static std::shared_ptr<T> Instance(Args&&... args);
};

template <typename T, typename Cleaner = std::function<void(T)>>
requires std::is_invocable_v<Cleaner, T>
class RAII {
public:
    RAII(T object, Cleaner cleaner);
    RAII(const RAII&) = delete;
    RAII(RAII&&) = delete;
    ~RAII();

    const T& Object() const noexcept;
private:
    T object_;
    Cleaner cleaner_;
};

class MappedReadOnlyFile {
public:
    MappedReadOnlyFile() = default;
    MappedReadOnlyFile(const MappedReadOnlyFile&) = delete;
    MappedReadOnlyFile(MappedReadOnlyFile&& other) noexcept;
    MappedReadOnlyFile& operator=(MappedReadOnlyFile&& other) noexcept;
    ~MappedReadOnlyFile();

    void Map(const std::string& path);
    void Unmap() noexcept;
    std::size_t Size() const noexcept;
    const char* Data() const noexcept;
    const std::string& Path() const noexcept;
private:
    std::string path_;
    const char* data_ = nullptr;
    std::size_t size_ = 0;
};

template <typename T, typename U, typename Ret = T>
concept Addable = requires(T t, U u) {
    { t + u } -> std::convertible_to<Ret>;
};

}

#endif // UTIL_H

#include "util.h"
#include <execinfo.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <algorithm>
#include <cassert>
#include <cerrno>
#include <iterator>
#include <sstream>
#include <system_error>

namespace ws {

std::string StringToLower(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), ::tolower);
    return str;
}

std::string StringToUpper(std::string str) noexcept {
    std::ranges::transform(str, str.begin(), ::toupper);
    return str;
}

std::string ReplaceAllSubstring(std::string_view str, std::string_view from, std::string_view to) noexcept {
    std::ostringstream oss;
    std::size_t pos = 0;
    while ((pos = str.find(from, pos)) != std::string_view::npos) {
        oss << str.substr(0, pos) << to;
        pos += from.length();
    }
    oss << str.substr(pos);
    return oss.str();
}

std::vector<std::string> SplitString(const std::string& str, const std::regex& pattern) noexcept {
    std::sregex_token_iterator iter(str.begin(), str.end(), pattern, -1);
    std::sregex_token_iterator end;
    return {iter, end};
}

std::vector<std::string> SplitStringToLines(const std::string& str) noexcept {
    static const std::regex line_break("\r?\n");
    return SplitString(str, line_break);
}

YAML::Node LoadYamlString(std::string_view str, std::initializer_list<std::string_view> required_fields) {
    YAML::Node node = YAML::Load(std::string(str));
    for (auto field : required_fields) {
        if (!node[field]) {
            throw std::runtime_error(fmt::format("Required field '{}' is missing", field));
        }
    }
    return node;
}

void ThrowIfYamlFieldIsNotScalar(const YAML::Node& node, std::string_view field) {
    if (!node[field] || !node[field].IsScalar()) {
        throw std::runtime_error(fmt::format("Field '{}' is not a scalar", field));
    }
}

constexpr bool IsValidFileDescriptor(FileDescriptor fd) noexcept {
    return fd != invalid_file_descriptor;
}

void SetFileDescriptorAsNonblocking(FileDescriptor fd) {
    int flags = fcntl(fd, F_GETFL);
    if (flags == -1 || fcntl(fd, F_SETFL, flags | O_NONBLOCK) == -1) {
        throwLastSystemError();
    }
}

[[noreturn]] void ThrowLastSystemError() {
    throw std::system_error(errno, std::generic_category());
}

std::uint32_t CurrentThreadId() noexcept {
    return static_cast<std::uint32_t>(syscall(SYS_gettid));
}

void Backtrace(std::vector<std::string>& stack, std::size_t size, std::size_t skip) noexcept {
    void* buffer[size];
    std::size_t count = backtrace(buffer, static_cast<int>(size));
    char** symbols = backtrace_symbols(buffer + skip, count - skip);
    if (symbols) {
        for (std::size_t i = 0; i < count - skip; ++i) {
            stack.push_back(symbols[i]);
        }
        free(symbols);
    }
}

std::string Backtrace(std::size_t size, std::size_t skip, std::string_view prefix) noexcept {
    std::vector<std::string> stack;
    Backtrace(stack, size, skip);
    std::ostringstream oss;
    for (const auto& frame : stack) {
        oss << prefix << frame << "\n";
    }
    return oss.str();
}

template <typename T, typename... Args>
T& Singleton<T, Args...>::Instance(Args&&... args) {
    static T instance(std::forward<Args>(args)...);
    return instance;
}

template <typename T, typename... Args>
std::shared_ptr<T> SingletonPtr<T, Args...>::Instance(Args&&... args) {
    static std::shared_ptr<T> instance = std::make_shared<T>(std::forward<Args>(args)...);
    return instance;
}

template <typename T, typename Cleaner>
requires std::is_invocable_v<Cleaner, T>
RAII<T, Cleaner>::RAII(T object, Cleaner cleaner)
    : object_(object), cleaner_(cleaner) {}

template <typename T, typename Cleaner>
requires std::is_invocable_v<Cleaner, T>
RAII<T, Cleaner>::~RAII() {
    cleaner_(object_);
}

template <typename T, typename Cleaner>
requires std::is_invocable_v<Cleaner, T>
const T& RAII<T, Cleaner>::Object() const noexcept {
    return object_;
}

MappedReadOnlyFile::MappedReadOnlyFile(MappedReadOnlyFile&& other) noexcept
    : path_(std::move(other.path_)), data_(other.data_), size_(other.size_) {
    other.data_ = nullptr;
    other.size_ = 0;
}

MappedReadOnlyFile& MappedReadOnlyFile::operator=(MappedReadOnlyFile&& other) noexcept {
    if (this != &other) {
        Unmap();
        path_ = std::move(other.path_);
        data_ = other.data_;
        size_ = other.size_;
        other.data_ = nullptr;
        other.size_ = 0;
    }
    return *this;
}

MappedReadOnlyFile::~MappedReadOnlyFile() {
    Unmap();
}

void MappedReadOnlyFile::Map(const std::string& path) {
    int fd = open(path.c_str(), O_RDONLY);
    if (fd == -1) {
        throwLastSystemError();
    }
    struct stat sb;
    if (fstat(fd, &sb) == -1) {
        close(fd);
        throwLastSystemError();
    }
    size_ = static_cast<std::size_t>(sb.st_size);
    data_ = static_cast<const char*>(mmap(nullptr, size_, PROT_READ, MAP_PRIVATE, fd, 0));
    if (data_ == MAP_FAILED) {
        close(fd);
        throwLastSystemError();
    }
    path_ = path;
    close(fd);
}

void MappedReadOnlyFile::Unmap() noexcept {
    if (data_) {
        munmap(const_cast<char*>(data_), size_);
        data_ = nullptr;
        size_ = 0;
        path_.clear();
    }
}

std::size_t MappedReadOnlyFile::Size() const noexcept {
    return size_;
}

const char* MappedReadOnlyFile::Data() const noexcept {
    return data_;
}

const std::string& MappedReadOnlyFile::Path() const noexcept {
    return path_;
}

}
